# inventory.py
# Simple CLI inventory manager using JSON persistence (inventory.json)
# Supports: add, update, remove, get, list, import, export

import argparse
import json
import os
import sys
import tempfile
import csv
from decimal import Decimal

STORAGE_FILE = "inventory.json"

# Utility helpers

def atomic_write(path, data_text):
    # write to temp file and replace to avoid corruption
    dirpath = os.path.dirname(os.path.abspath(path)) or '.'
    fd, tmp = tempfile.mkstemp(dir=dirpath, prefix=".tmp_inv_")
    try:
        with os.fdopen(fd, 'w', encoding='utf-8') as f:
            f.write(data_text)
        os.replace(tmp, path)
    finally:
        if os.path.exists(tmp):
            try:
                os.remove(tmp)
            except Exception:
                pass


def load_inventory():
    if not os.path.exists(STORAGE_FILE):
        return []
    with open(STORAGE_FILE, 'r', encoding='utf-8') as f:
        try:
            data = json.load(f)
            if not isinstance(data, list):
                return []
            return data
        except Exception:
            return []


def save_inventory(items):
    atomic_write(STORAGE_FILE, json.dumps(items, indent=2, ensure_ascii=False))


def find_item(items, item_id):
    for it in items:
        if it.get('id') == item_id:
            return it
    return None


def validate_item_fields(id_, name, quantity, price, require_all=True):
    if require_all:
        if id_ is None or name is None or quantity is None or price is None:
            raise ValueError("Missing required fields: id, name, quantity, price")
    if quantity is not None:
        try:
            qty = int(quantity)
        except Exception:
            raise ValueError(f"quantity must be integer, got '{quantity}'")
        if qty < 0:
            raise ValueError("quantity must be >= 0")
    if price is not None:
        try:
            p = Decimal(str(price))
        except Exception:
            raise ValueError(f"price must be numeric, got '{price}'")
        if p < 0:
            raise ValueError("price must be >= 0")


def cmd_add(args):
    try:
        validate_item_fields(args.id, args.name, args.quantity, args.price, require_all=True)
    except ValueError as e:
        print(f"Error: {e}", file=sys.stderr)
        return 2
    items = load_inventory()
    if find_item(items, args.id) is not None:
        print(f"Error: Item with id {args.id} already exists.", file=sys.stderr)
        return 3
    item = {
        'id': args.id,
        'name': args.name,
        'quantity': int(args.quantity),
        'price': float(Decimal(str(args.price)))
    }
    items.append(item)
    save_inventory(items)
    print(f"Added item {args.id}")
    return 0


def cmd_update(args):
    if args.name is None and args.quantity is None and args.price is None:
        print("Error: At least one of --name, --quantity, --price must be provided.", file=sys.stderr)
        return 2
    items = load_inventory()
    it = find_item(items, args.id)
    if it is None:
        print(f"Error: Item with id {args.id} not found.", file=sys.stderr)
        return 3
    try:
        validate_item_fields(args.id, args.name if args.name is not None else it.get('name'), args.quantity if args.quantity is not None else it.get('quantity'), args.price if args.price is not None else it.get('price'), require_all=False)
    except ValueError as e:
        print(f"Error: {e}", file=sys.stderr)
        return 4
    if args.name is not None:
        it['name'] = args.name
    if args.quantity is not None:
        it['quantity'] = int(args.quantity)
    if args.price is not None:
        it['price'] = float(Decimal(str(args.price)))
    save_inventory(items)
    print(f"Updated item {args.id}")
    return 0


def cmd_remove(args):
    items = load_inventory()
    it = find_item(items, args.id)
    if it is None:
        print(f"Error: Item with id {args.id} not found.", file=sys.stderr)
        return 3
    items = [x for x in items if x.get('id') != args.id]
    save_inventory(items)
    print(f"Removed item {args.id}")
    return 0


def cmd_get(args):
    items = load_inventory()
    it = find_item(items, args.id)
    if it is None:
        print(f"Error: Item with id {args.id} not found.", file=sys.stderr)
        return 3
    print(json.dumps(it, indent=2, ensure_ascii=False))
    return 0


def cmd_list(args):
    items = load_inventory()
    print(json.dumps(items, indent=2, ensure_ascii=False))
    return 0


def cmd_export(args):
    items = load_inventory()
    with open(args.file, 'w', encoding='utf-8') as f:
        json.dump(items, f, indent=2, ensure_ascii=False)
    print(f"Exported {len(items)} items to {args.file}")
    return 0


def parse_csv_row(rownum, row):
    # Expects exactly 4 columns: id,name,quantity,price
    if len(row) < 4:
        raise ValueError(f"row has too few columns: {row}")
    id_ = row[0].strip()
    name = row[1].strip() if len(row) > 1 else ''
    quantity = row[2].strip() if len(row) > 2 else ''
    price = row[3].strip() if len(row) > 3 else ''
    if id_ == '' or name == '' or quantity == '' or price == '':
        raise ValueError("missing required field")
    try:
        qty = int(quantity)
    except Exception:
        raise ValueError(f"invalid integer for quantity: '{quantity}'")
    try:
        p = Decimal(price)
    except Exception:
        raise ValueError(f"invalid numeric for price: '{price}'")
    if qty < 0:
        raise ValueError("quantity must be >= 0")
    if p < 0:
        raise ValueError("price must be >= 0")
    return {
        'id': id_,
        'name': name,
        'quantity': qty,
        'price': float(p)
    }


def cmd_import(args):
    # Import CSV. Policy documented in README: duplicates are SKIPPED; malformed rows are SKIPPED with warning
    if not os.path.exists(args.file):
        print(f"Error: import file {args.file} not found.", file=sys.stderr)
        return 2
    items = load_inventory()
    existing_ids = {it['id'] for it in items}
    added = 0
    skipped_duplicate = 0
    skipped_malformed = 0
    with open(args.file, newline='', encoding='utf-8') as csvfile:
        reader = csv.reader(csvfile)
        rows = list(reader)
        # handle optional header: if first row's first cell lower == 'id' treat as header
        start = 0
        if len(rows) > 0 and len(rows[0]) > 0 and rows[0][0].strip().lower() == 'id':
            start = 1
        for idx, row in enumerate(rows[start:], start + 1):
            try:
                parsed = parse_csv_row(idx, row)
            except ValueError as e:
                print(f"Import: Skipped malformed row {idx}: {e}")
                skipped_malformed += 1
                continue
            if parsed['id'] in existing_ids:
                print(f"Import: Skipped duplicate id {parsed['id']}")
                skipped_duplicate += 1
                continue
            items.append(parsed)
            existing_ids.add(parsed['id'])
            added += 1
            print(f"Import: Added {parsed['id']}")
    save_inventory(items)
    print(f"Import complete. Added={added} SkippedDuplicates={skipped_duplicate} SkippedMalformed={skipped_malformed}")
    return 0


def main():
    parser = argparse.ArgumentParser(description='Inventory manager')
    sub = parser.add_subparsers(dest='cmd')

    p_add = sub.add_parser('add')
    p_add.add_argument('--id', required=True)
    p_add.add_argument('--name', required=True)
    p_add.add_argument('--quantity', required=True)
    p_add.add_argument('--price', required=True)

    p_update = sub.add_parser('update')
    p_update.add_argument('--id', required=True)
    p_update.add_argument('--name')
    p_update.add_argument('--quantity')
    p_update.add_argument('--price')

    p_remove = sub.add_parser('remove')
    p_remove.add_argument('--id', required=True)

    p_get = sub.add_parser('get')
    p_get.add_argument('--id', required=True)

    p_list = sub.add_parser('list')

    p_import = sub.add_parser('import')
    p_import.add_argument('--file', required=True)

    p_export = sub.add_parser('export')
    p_export.add_argument('--file', required=True)

    args = parser.parse_args()
    if args.cmd is None:
        parser.print_help()
        sys.exit(1)
    try:
        if args.cmd == 'add':
            rc = cmd_add(args)
        elif args.cmd == 'update':
            rc = cmd_update(args)
        elif args.cmd == 'remove':
            rc = cmd_remove(args)
        elif args.cmd == 'get':
            rc = cmd_get(args)
        elif args.cmd == 'list':
            rc = cmd_list(args)
        elif args.cmd == 'import':
            rc = cmd_import(args)
        elif args.cmd == 'export':
            rc = cmd_export(args)
        else:
            print(f"Unknown command {args.cmd}", file=sys.stderr)
            rc = 1
    except Exception as e:
        print(f"Unhandled error: {e}", file=sys.stderr)
        rc = 100
    sys.exit(rc)

